-- ============================================================================
-- قرار الأحياء المغلقة في إسطنبول: الخبر الذي لم يُنشر
-- ============================================================================
-- المقال موجود وهو الأكثر قراءةً عندنا في هذا الباب
-- (istanbul-closed-neighborhoods-lift-2026، 337 قراءة)، والاجتماع التنسيقي
-- أكّد رقمه. لكنّ جدول updates لا يحوي صفّاً يشير إليه — فُحصت الصفوف
-- الـ27 الفعّالة كلّها. فلم يظهر القرار في شريط الصفحة الرئيسية، ولا وصل إلى
-- /updates، ولا أطلق إشعاراً. وصاحب الموقع محقّ: لم يُنشر خبراً قطّ.
--
-- ── ما هو متحقَّق منه، وما هو منقول ────────────────────────────────────
--
-- متحقَّق بطريقين: بقاء **خمسة** أحياء مغلقة في إسطنبول، وجدول zones عندنا
-- يطابق القائمة الرسمية حيّاً بحيّ — ÜNİVERSİTE (أفجيلار)، وZAFER وKOZA
-- (إسنيورت)، وMOLLA HÜSREV (الفاتح)، وBEŞYOL (كوتشوك تشكمجة). وأكّدت
-- المديرية العدد ثانيةً في الاجتماع التنسيقي بعد قائمة 7 حزيران.
--
-- منقول لا متحقَّق منه عندنا: أنّ القائمة كانت 54 حيّاً من نحو 961. وهو من
-- عرض المديرية نفسها كما نقله UCSO، ونُسب في المتن إلى مصدره صراحةً بدل أن
-- يُقدَّم إحصاءً من عندنا — لأنّ بياناتنا لا تؤكّده.
--
-- ── رقم بدا خطأً وليس كذلك ──────────────────────────────────────────────
--
-- المقال يقول 49 حيّاً أُعيد فتحها، وجدولنا فيه 50 صفّاً «reopened» لإسطنبول
-- (55 إجمالاً = 5 مغلقة + 50 مفتوحة). والفارق حيٌّ أُعيد فتحه في موجة أسبق،
-- قبل قائمة الـ54. فالرقمان صحيحان لما يصفانه، ولم يُمسّ أيٌّ منهما.
--
-- ── وما امتنعتُ عن نشره عمداً ───────────────────────────────────────────
--
-- جدولنا يُظهر 764 حيّاً ما زال مغلقاً على مستوى تركيا. وهذا الرقم ليس في
-- المتن. فحداثة بيانات الأحياء أحرقت هذا الموقع مرّةً — قائمة أورفا 2022
-- نُشرت بوصفها إرشاداً لعام 2026 — والعدّ الوطني في عنوان خبرٍ هو بالضبط
-- الادّعاء الذي يفسد صامتاً. خمسة إسطنبول أكّدتها المديرية مرّتين هذا العام؛
-- والصورة الوطنية تُترك للفاحص، يعرض حال كل ولاية بتاريخها.
--
-- آمن لإعادة التشغيل.
-- ============================================================================

INSERT INTO updates (type, title, summary, content, link, source_name, category, date, active, pinned)
SELECT 'news', 'رسمي: خمسة أحياء فقط بقيت مغلقة أمام تسجيل الأجانب في إسطنبول — وما عداها مفتوح', 'أكّدت مديرية إدارة الهجرة في ولاية إسطنبول أنّ الأحياء المغلقة أمام تسجيل الأجانب انحصرت في <strong>خمسة</strong> فقط، وأنّ ما عداها في الولاية مفتوح. والخمسة هي: ÜNİVERSİTE في أفجيلار، وZAFER وKOZA في إسنيورت، وMOLLA HÜSREV في الفاتح، وBEŞYOL في كوتشوك تشكمجة. وأداة فاحص الأحياء عندنا تطابق القائمة الرسمية حيّاً بحيّ.', '<div style="background:#ecfdf5;border:2px solid #10b981;border-radius:12px;padding:18px 22px;margin:0 0 20px;"><p style="margin:0 0 10px;font-size:17px;"><strong>الخلاصة</strong></p><p style="margin:0;">إن كنت تبحث عن سكن في إسطنبول أو تريد نقل قيدك إليها، فـ<strong>خمسة أحياء فقط</strong> مغلقة أمام تسجيل الأجانب. وكلّ ما عداها في الولاية <strong>مفتوح</strong> — ومن يظنّ إسطنبول مغلقةً كلّها يمتنع عن إجراءٍ يستطيعه.</p></div><h3>الأحياء الخمسة</h3><table><thead><tr><th>الحي</th><th>القضاء</th></tr></thead><tbody><tr><td><strong>ÜNİVERSİTE MAHALLESİ</strong></td><td>أفجيلار <span dir="ltr">(Avcılar)</span></td></tr><tr><td><strong>ZAFER MAHALLESİ</strong></td><td>إسنيورت <span dir="ltr">(Esenyurt)</span></td></tr><tr><td><strong>KOZA MAHALLESİ</strong></td><td>إسنيورت <span dir="ltr">(Esenyurt)</span></td></tr><tr><td><strong>MOLLA HÜSREV MAHALLESİ</strong></td><td>الفاتح <span dir="ltr">(Fatih)</span></td></tr><tr><td><strong>BEŞYOL MAHALLESİ</strong></td><td>كوتشوك تشكمجة <span dir="ltr">(Küçükçekmece)</span></td></tr></tbody></table><p>وهذه القائمة نفسها التي صدرت في <strong>7 حزيران/يونيو 2026</strong>، <strong>وأكّدتها المديرية مرّةً ثانية</strong> في اجتماع تنسيقي مع منظمات المجتمع المدني. فمن يسأل: هل تغيّرت بعد ذلك؟ الجواب لا.</p><h3>ما معنى «مغلق» هنا؟</h3><p>الإغلاق يخصّ <strong>تسجيل الأجانب في الحي</strong> — أي قيد العنوان ونقل السكن إليه. وهو ليس منعاً من دخول الحي ولا من العمل فيه ولا من زيارته. والخلط بين الأمرين يجعل الناس تتجنّب أحياءً مفتوحة بلا سبب.</p><h3>لا تعتمد على قائمةٍ منقولة — افحص حيّك</h3><p>القوائم المتداولة على مجموعات التواصل تتأخّر شهوراً عن القرارات، وقد رأينا قوائم من سنوات سابقة تُنشر بوصفها حالية. <a href="/zones/%C4%B0stanbul"><strong>افحص حيّك بالاسم التركي في فاحص الأحياء ←</strong></a> وتظهر لك حالته كما هي عندنا.</p><p>وإن كنت خارج إسطنبول فالحال يختلف بين ولاية وأخرى — <a href="/zones">افتح الفاحص واختر ولايتك</a>.</p><h3>وللسياق الكامل</h3><p>ذكرت المديرية في عرضها أنّ القائمة كانت <strong>54 حيّاً</strong> من نحو <strong>961 حيّاً</strong> في الولاية قبل القرار — وهذا رقمٌ نقلاً عن عرض المديرية، لا إحصاءً من عندنا. والقرار جاء ضمن موجة وطنية بدأت في 6 حزيران/يونيو 2026.</p><p style="margin-top:1rem;"><a href="/article/istanbul-closed-neighborhoods-lift-2026"><strong>التفصيل الكامل للقرار وأسماء الأحياء ←</strong></a></p><p>وللمقيم في إسطنبول أيضاً: <a href="/article/istanbul-goc-randevu-noter-2026">تسليم أوراق الإقامة عبر النوتر</a> • <a href="/article/kimlik-data-update">تحديث بيانات الكملك والعنوان</a></p>', '/article/istanbul-closed-neighborhoods-lift-2026', 'مديرية إدارة الهجرة في ولاية إسطنبول (İstanbul İl Göç İdaresi Müdürlüğü) — القائمة الرسمية الصادرة في 7 حزيران/يونيو 2026، وتأكيدها في اجتماع تنسيقي مع منظمات المجتمع المدني نقله اتحاد منظمات المجتمع المدني للتنمية (UCSO) بوصفه مشاركاً', 'official', CURRENT_DATE, true, true
WHERE NOT EXISTS (SELECT 1 FROM updates WHERE link = '/article/istanbul-closed-neighborhoods-lift-2026');

-- خبر إذن السفر أُدرج بتاريخ 2026-08-07 بينما تُرشِّح الصفحة الرئيسية على
-- تاريخ UTC — فبقي محجوزاً كخبرٍ مستقبلي ولم يظهر. CURRENT_DATE هو الساعة
-- نفسها التي يقارن بها المرشِّح.
UPDATE updates SET date = CURRENT_DATE
WHERE link = '/article/travel-permit' AND date > CURRENT_DATE;

-- ═══════════════════════════════════════════════════════════════════════════
DO $check$
DECLARE n int; bad int;
BEGIN
    SELECT count(*) INTO n FROM updates WHERE link = '/article/istanbul-closed-neighborhoods-lift-2026';
    IF n <> 1 THEN RAISE EXCEPTION 'expected exactly one news row, found %', n; END IF;

    SELECT count(*) INTO bad FROM updates u
     WHERE u.link = '/article/istanbul-closed-neighborhoods-lift-2026'
       AND NOT EXISTS (SELECT 1 FROM articles a WHERE a.status = 'approved'
                        AND '/article/' || a.slug = u.link);
    IF bad > 0 THEN RAISE EXCEPTION 'the news links to an article that is not live'; END IF;

    -- الأحياء الخمسة في المتن يجب أن تطابق الجدول، لا الذاكرة
    SELECT count(*) INTO bad FROM zones z
     WHERE z.city = 'İstanbul' AND z.status = 'closed'
       AND NOT EXISTS (SELECT 1 FROM updates u WHERE u.link = '/article/istanbul-closed-neighborhoods-lift-2026'
                        AND u.content LIKE '%' || z.neighborhood || '%');
    IF bad > 0 THEN RAISE EXCEPTION 'the news omits % closed neighbourhood(s) that the zones table lists', bad; END IF;
END
$check$;

SELECT 'news row created' AS البند, (count(*) = 1)::boolean AS سليم
FROM updates WHERE link = '/article/istanbul-closed-neighborhoods-lift-2026'
UNION ALL
SELECT 'pinned + active', bool_and(pinned AND active) FROM updates WHERE link = '/article/istanbul-closed-neighborhoods-lift-2026'
UNION ALL
SELECT 'İstanbul closed = 5', (count(*) = 5)::boolean FROM zones WHERE city = 'İstanbul' AND status = 'closed'
UNION ALL
SELECT 'links to the live article', (count(*) = 1)::boolean
FROM articles WHERE slug = 'istanbul-closed-neighborhoods-lift-2026' AND status = 'approved';
